/* Career Radar V5.5 evaluation lab — browser-local and zero OpenAI calls. */
(()=>{
  const section=`<section class="view hide" id="calibration"><div class="eyebrow">Career Radar V5.5 / evidence evaluation</div><h1>Is this application worth pursuing?</h1><p class="sub">Compare your evidence with published vacancy requirements. You make the final application decision. Local analysis only; no OpenAI request or charge.</p><div class="panel"><div class="fields"><div class="field"><label>Minimum salary (£)</label><input id="calSalary" type="number" min="0" value="35000"></div><div class="field"><label>Minimum FTC duration (months)</label><input id="calMonths" type="number" min="0" value="6"></div><div class="field wide"><label>Real vacancy from your latest Adzuna search</label><select id="calJob"><option value="">Or paste a vacancy below</option></select></div><div class="field wide"><label><input type="checkbox" id="calLinked"> The pasted text below is the full advert for the selected listing (reuse its salary, location, contract and ID)</label><small>Leave unticked if you pasted a different vacancy; nothing from the selected listing is then reused.</small></div><div class="field wide"><label>Vacancy title (optional if selected above)</label><input id="calTitle" placeholder="e.g. Learning Operations Coordinator"></div><div class="field wide"><label>Employer (optional)</label><input id="calEmployer" placeholder="e.g. Deutsche Bank"></div><div class="field wide"><label>Vacancy description (optional if selected above)</label><textarea id="calDescription" rows="7" placeholder="Paste the full responsibilities and essential/desirable requirements. Short summaries are not rated."></textarea></div><div class="field wide"><label><input type="checkbox" id="calFull"> I pasted the full original advert, including its requirements.</label><small>Search results are summaries. They can identify leads, but do not support a full fit score.</small></div><div class="field wide"><label for="calSource">Original vacancy URL (optional for pasted adverts)</label><input id="calSource" type="url" placeholder="Paste the address of the original advert"></div><div class="field wide"><label for="calSector">Employer sector (advisory context)</label><select id="calSector"><option value="">Detect from the advert (shown with its basis)</option><option value="none">Do not use sector core skills</option></select><small>Sector relevance is shown separately from published essential criteria and does not change scoring.</small></div><div class="field wide"><label><input type="checkbox" id="calIntel" checked> Include limited intelligence</label><small>Dated employer snapshots, advert questions and comparisons within this search. No automatic web research or paid calls.</small></div><div class="row wide"><button class="btn" id="calEvaluate">Evaluate evidence</button><span class="pill" id="calStatus">Loading model…</span></div></div><div class="callout">Evidence and context are separate. Limited intelligence adds sources and questions; it never changes your score or recommendation. Unknown employers receive no penalty.</div></div><div class="sectionhead"><h2>Evidence, uncertainty and employer context</h2></div><div class="panel" id="calOutput"><p class="sub">Choose a complete vacancy and your evidence profile. You decide whether to apply, skip or investigate.</p></div></section>`;
  const anchor=document.getElementById('semantic')||document.getElementById('matching');
  anchor.insertAdjacentHTML('afterend',section);
  const nav='<button data-view="calibration"><span>⚖</span> Fit Calibration (V5.5)</button>';
  document.querySelector('.sidebar .nav').insertAdjacentHTML('beforeend',nav);
  document.querySelector('.mobile').insertAdjacentHTML('beforeend',nav);
  document.querySelectorAll('[data-view="calibration"]').forEach(b=>b.onclick=()=>go('calibration'));
  const el=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const feedbackPanel=`<div class="panel" id="humanReviewPanel" style="margin-top:20px"><h2>Your review and improvement cycle</h2><p class="sub">Review the evaluation shown above. Your application choice and your assessment of the engine are separate. Saved in this browser; export a backup before clearing browser data. No automatic rule changes or model training.</p><div class="fields"><div class="field"><label for="fbDecision">Your application decision</label><select id="fbDecision"><option value="">Choose…</option><option value="apply">Apply</option><option value="skip">Skip</option><option value="investigate">Investigate</option></select></div><div class="field"><label for="fbAssessment">How accurate is this evaluation?</label><select id="fbAssessment"><option value="">Choose…</option><option value="accurate">Reasonable / accurate</option><option value="too_positive">Too positive</option><option value="too_negative">Too negative</option><option value="unsure">Not sure yet</option></select></div><div class="field"><label for="fbReason">Main reason</label><select id="fbReason"><option value="">Choose…</option><option value="evidence_match">Evidence matching</option><option value="requirement_extraction">Missing / incorrect requirement</option><option value="eligibility">Eligibility check</option><option value="source_quality">Source quality</option><option value="recommendation">Recommendation</option><option value="salary_preference">My salary preference</option><option value="commute_preference">My commute / attendance preference</option><option value="employer_preference">My employer preference</option><option value="role_preference">My role preference</option><option value="other">Other</option></select></div><div class="field"><label for="fbRequirement">Related requirement (optional)</label><select id="fbRequirement"><option value="">Whole evaluation</option></select></div><div class="field wide"><label for="fbNote">What should we understand or correct?</label><textarea id="fbNote" rows="3" maxlength="4000" placeholder="Explain your judgement. Avoid private information you would not want in an exported review."></textarea></div><div class="row wide"><button class="btn" id="fbSave">Save my review</button><span id="fbStatus" role="status">Evaluate a vacancy first.</span></div></div><h3>Periodic review</h3><div class="row"><label for="fbPeriod">Review period</label><select id="fbPeriod"><option value="7">Last 7 days</option><option value="30" selected>Last 30 days</option><option value="90">Last 90 days</option></select><button id="fbRefresh">Refresh review summary</button><button id="fbExport">Export reviews and improvement report</button></div><div id="fbCycle"></div><p class="sub">Recurring reported errors become review candidates. Proposed changes must pass regression and fixed-sample checks and receive owner approval before a versioned release. The previous release remains available for rollback.</p></div>`;
  el('calOutput').insertAdjacentHTML('afterend',feedbackPanel);
  let reviewContext=null,feedback=null;
  const feedbackReady=import('/feedback-cycle.mjs').then(m=>{feedback=m;if(typeof m.summarizeFeedback==='function')refreshCycle();}).catch(()=>el('fbStatus').textContent='Review module unavailable; evaluation remains usable.');
  const ledgerKey='career-radar-review-ledger-v1';
  function readLedger(){try{const r=JSON.parse(localStorage.getItem(ledgerKey)||'[]');if(!Array.isArray(r))throw Error('Invalid review ledger');return r;}catch(e){if(typeof localStorage==='undefined')return [];throw e;}}
  function cycleOptions(){return {periodEnd:new Date().toISOString(),periodDays:Number(el('fbPeriod').value)||30};}
  function refreshCycle(){try{if(!feedback?.summarizeFeedback)return;const r=feedback.summarizeFeedback(readLedger(),cycleOptions());el('fbCycle').innerHTML=`<p><b>${r.effective_reviews} contextualised review(s)</b> from ${r.events} saved event(s) in this period.</p><p>Evaluation judgements: ${Object.entries(r.by_assessment).map(([k,v])=>esc(k)+': '+v).join(' · ')||'None yet'}</p><p>${r.candidate_improvements.length} reported error area(s) for review. Decisions based on personal preferences are recorded separately.</p><ul>${r.candidate_improvements.map(x=>`<li>${esc(x.area)} · ${x.distinct_adverts} distinct adverts · ${esc(x.status)}</li>`).join('')}</ul><p>No rules have been changed automatically. These counts do not measure model accuracy.</p>`;}catch{el('fbStatus').textContent='Could not read the review ledger; existing data was not overwritten.';}}
  el('fbRefresh').onclick=refreshCycle;el('fbPeriod').onchange=refreshCycle;
  el('fbSave').onclick=async()=>{try{await feedbackReady;if(!feedback?.createFeedbackRecord||!reviewContext)throw Error('Evaluate a vacancy before saving a review.');const records=readLedger(),previous=[...records].reverse().find(x=>x.source?.sha256===reviewContext.sourceHash&&x.context?.profile_sha256===reviewContext.profileHash&&x.engine_version===reviewContext.result.engine_version);const record=await feedback.createFeedbackRecord({...reviewContext,humanDecision:el('fbDecision').value,assessment:el('fbAssessment').value,reason:el('fbReason').value,requirementId:el('fbRequirement').value,rationale:el('fbNote').value,reviewedAt:new Date().toISOString(),supersedes:previous?.record_id||null});records.push(record);localStorage.setItem(ledgerKey,JSON.stringify(records));el('fbStatus').textContent='Review saved locally. No application sent and no rules changed.';refreshCycle();}catch(e){el('fbStatus').textContent=e.message||'Could not save review; existing data was not overwritten.';}};
  el('fbExport').onclick=async()=>{try{await feedbackReady;if(!feedback?.exportFeedback)throw Error('Review module unavailable');const data=await feedback.exportFeedback(readLedger(),cycleOptions()),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='career-radar-human-review-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url);el('fbStatus').textContent='Review backup exported. Includes advert snapshots and your notes; no CV text or CV quotations.';}catch(e){el('fbStatus').textContent=e.message||'Export failed';}};
  window.addEventListener('career-radar-start-review',async e=>{const jobs=window.__careerRadarJobs||[],index=jobs.findIndex(x=>String(x.id)===String(e.detail?.vacancyId));if(index<0)return;el('calJob').value=String(index);el('calLinked').checked=true;el('calTitle').value=jobs[index].title||'';el('calEmployer').value=jobs[index].company||'';el('calDescription').value='';el('calSource').value='';el('calFull').checked=false;go('calibration');await el('calEvaluate').onclick();el('fbDecision').value=e.detail.decision;el('fbStatus').textContent='Add your judgement and reason, then save the review. A summary still needs the full original advert for fit scoring.';});
  let model=null;
  import('/calibration-v54.mjs').then(m=>{model=m;el('calSector').innerHTML+=(m.SECTORS||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');el('calStatus').textContent='V5.5 model ready'}).catch(()=>el('calStatus').textContent='Model unavailable');
  let intelligence=null;const intelReady=import('/intelligence-v1.mjs').then(m=>intelligence=m).catch(()=>null);
  let evaluationRun=0;
  // Self-confirmations belong to one exact advert text; they are cleared when the text changes.
  let attestations={},attestedFor='';
  function updateJobs(){const jobs=window.__careerRadarJobs||[];el('calJob').innerHTML='<option value="">Paste a vacancy below</option>'+jobs.map((j,i)=>`<option value="${i}">${esc(j.title)} — ${esc(j.company)}</option>`).join('')}
  window.addEventListener('career-radar-results',updateJobs);updateJobs();
  el('calSector').onchange=()=>{if(el('calOutput').innerHTML.includes('data-attest')||el('calOutput').innerHTML.includes('Core skills basis'))el('calEvaluate').onclick();};
  el('calJob').onchange=()=>{el('calLinked').checked=false};
  const STATE={cv_quoted:'Evidenced (CV quote)',qualifier_unverified:'Partly evidenced',partial:'Partial — general statement',no_match_found:'No CV match found',not_assessed:'Not checked automatically',self_attested:'Confirmed by you',self_attested_partial:'Partly (your view)',absent_self_reported:'Not met (your view)',to_confirm:'Condition to confirm'};
  const hardTag=s=>s==='supported'?'Supported':s==='not_met'?'Not met':'Unknown';
  const OPTIONS=[['','Unsure / not yet checked'],['have','I have evidence'],['partial','Partly'],['no','I do not meet this']];
  function evidenceCell(req){
    const ad=`<div style="color:#647770;margin-top:5px">Ad: ${esc(req.source)}</div>${req.sources?.length>1?`<details><summary>${req.sources.length} source passages retained</summary>${req.sources.map(x=>`<p>${esc(x.text)}</p>`).join('')}</details>`:''}`;
    const quote=req.evidence?`<i>“${esc(req.evidence)}”</i>`:'';
    const select=`<div style="margin-top:5px"><select data-attest="${esc(req.id)}" aria-label="Your evidence for ${esc(req.label)}">${OPTIONS.map(([v,l])=>`<option value="${v}"${(req.attestation||'')===v?' selected':''}>${l}</option>`).join('')}</select></div>`;
    const auto=req.automated_state||req.evidence_state;
    if(req.match_mode==='manual')return `${req.evidence_state==='not_assessed'?'No automated matcher for this item — your CV was not searched for it.':'Your confirmation (not a CV quotation).'}${select}${ad}`;
    const note=auto==='no_match_found'?'Automated search found no matching CV sentence. Unknown, not absent — your CV may simply not mention it.':auto==='qualifier_unverified'?`Covers the category, not: ${esc((req.unverified_qualifiers||[]).join(', '))}.`:auto==='partial'?'General self-description; add a specific example.':'';
    return `${quote}${note?`<div>${note}</div>`:''}${req.attestation?'<div>Your confirmation is recorded separately from the CV.</div>':''}${auto!=='cv_quoted'||req.attestation?select:''}${ad}`;
  }
  function render(result,job,intel,inputNotes){
    const cov=result.coverage,m=cov.matching;
    const t=result.thresholds,pc=x=>x==null?'—':Math.round(x*100)+'%';
    const range=b=>b.low==null?'n/a':b.low===b.high?pc(b.low):`${pc(b.low)}–${pc(b.high)}`;
    const headline=result.fit_score!==null?`Published essentials met: ${range(t.essential)} <small>(need ≥${pc(t.essential.required)})</small> · Non-essential: ${range(t.non_essential)} <small>(need ≥${pc(t.non_essential.required)})</small>`:result.decision.startsWith('Investigate — full')?'Full advert needed':result.decision==='Skip'?'Not scored — hard constraint not met':'Unrated';
    const scoreLine=result.fit_score!==null?`<p class="sub">Overall evidence score ${result.fit_score}/100 (${esc(result.band)}) across ${Math.round(m.assessed_ratio*100)}% of requirement weight. A range means some items are still open; answer them below.</p>`:'';
    const sec=result.sector||{};const sectorLine=`<div class="callout"><b>Core skills basis</b><p>${sec.employer?`Employer sector: ${esc(sec.employer.label)}`:'Employer sector: not identified (no penalty)'}${sec.role?` · Role family from title: ${esc(sec.role.label)}`:''}${sec.source==='override'?' · set by you':''}.</p>${(sec.evidence||[]).length?`<small>Basis: ${sec.evidence.map(e=>`${esc(e.kind)} — “${esc(e.text)}”`).join(' · ')}</small>`:''}${(sec.ambiguous||[]).length?`<small> Ambiguous between: ${sec.ambiguous.map(esc).join(', ')}; choose one above if relevant.</small>`:''}<p class="sub">${result.requirements.filter(x=>x.inferred_core).length} listed categories have inferred role/sector relevance. This is advisory and does not change published importance or scoring.</p></div>`;
    const row=req=>`<tr><td><b>${esc(req.label)}</b><div style="color:#647770;font-size:12px">${esc(req.importance)}${req.core?' · <b>core</b>':''} · weight ${req.weight}</div>${req.core?`<small>${esc(req.importance_basis)}</small>`:''}</td><td>${esc(STATE[req.evidence_state]||'Unknown')}</td><td style="font-size:12px">${evidenceCell(req)}</td></tr>`;
    const candidate=result.requirements.filter(x=>x.match_mode!=='condition');
    const essentialRows=candidate.filter(x=>x.importance==='essential').map(row).join('');
    const otherRows=candidate.filter(x=>x.importance!=='essential').map(row).join('');
    const table=(rows,empty)=>rows?`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;text-align:left;font-size:13px"><thead><tr><th>Requirement / weight</th><th>Status</th><th>Evidence and source</th></tr></thead><tbody>${rows}</tbody></table></div>`:`<p class="sub">${empty}</p>`;
    const conditions=result.pre_employment_conditions.map(c=>`<li><b>${esc(c.label)}</b><br><small>${esc(c.source)}</small></li>`).join('');
    const hard=result.hard_constraints.map(x=>`<div style="margin:6px 0">${esc(hardTag(x.status))} — <b>${esc(x.name)}</b>: ${esc(x.source)}</div>`).join('')||'No hard criteria configured';
    const extraction=result.extraction_summary;
    const audit=result.extraction_audit.map(x=>`<tr><td>${esc(x.unit_id)} · ${esc(x.section)}<br><b>${esc(x.disposition.replaceAll('_',' '))}</b></td><td>${esc(x.source)}<br><small>${esc(x.reason)}</small></td></tr>`).join('');
    const actions=result.verification_actions.filter(x=>x.kind==='eligibility'||x.kind==='qualifier').map(x=>`<li><b>${esc(x.criterion)}</b>: ${esc(x.action)}</li>`).join('');
    const tailor=result.tailoring_examples.slice(0,3).map(x=>`<li><b>${esc(x.criterion)}</b>: ${esc(x.what_to_evidence)}<div><i>“${esc(x.evidence)}”</i></div><small>Published duty: ${esc(x.source)}</small></li>`).join('');
    const unsupported=result.tailoring_prompts.map(x=>`<li><b>${esc(x.criterion)}</b>: ${esc(x.what_to_evidence)}</li>`).join('');
    const ev=cov.candidate_evidence;
    const layers=`<div class="callout"><b>What this assessment covers</b><ul><li><b>Source:</b> ${cov.source.kind==='full'?'full advert (as declared by you)':'provider summary'} · ${cov.source.word_count} words.</li><li><b>Extraction:</b> ${extraction.source_units} source units → ${cov.extraction.candidate_requirements} candidate requirements, ${cov.extraction.conditions} pre-employment condition(s), ${extraction.excluded_units} excluded, ${extraction.context_unreviewed_units} unresolved.</li><li><b>Matching:</b> ${m.automated} checked automatically against your CV; ${m.manual} have no automated matcher (${m.confirmed_by_user} confirmed by you). ${Math.round(m.assessed_ratio*100)}% of requirement weight is assessed.</li><li><b>Your evidence:</b> ${ev.cv_quoted} CV-quoted · ${ev.qualifier_unverified+ev.partial} partial · ${ev.no_match_found} no match found · ${ev.self_attested+ev.self_attested_partial} self-confirmed · ${ev.absent_self_reported} not met (your view) · ${ev.not_assessed} not yet checked.</li><li><b>Eligibility:</b> ${esc(cov.eligibility.status)}${cov.eligibility.unknown.length?` — unknown: ${esc(cov.eligibility.unknown.join(', '))}`:''}${cov.eligibility.not_met.length?` — not met: ${esc(cov.eligibility.not_met.join(', '))}`:''}.</li></ul><small>${esc(result.score_meaning)}</small></div>`;
    const provenance=inputNotes.length?`<div class="callout"><b>Input provenance</b><ul>${inputNotes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'';
    return `<div class="row" style="justify-content:space-between;align-items:center"><div><div class="eyebrow">${esc(result.version)} · ${esc(job.title)} · evaluated ${esc(result.evaluation_date)}</div><h2 style="margin:6px 0">${headline}</h2></div><span class="pill">Confidence: ${esc(result.confidence.label)}</span></div><div class="callout"><b>${esc(result.decision)}</b><div style="margin-top:8px">${esc(result.decision_reason)}</div></div>${scoreLine}${provenance}${sectorLine}<h3>Published essential criteria (need ≥${pc(t?.essential?.required)})</h3>${table(essentialRows,'No essential criteria detected.')}<h3>Next checks</h3>${actions?`<ul>${actions}</ul>`:'<p class="sub">No outstanding eligibility checks.</p>'}<h3>Pre-employment conditions</h3>${conditions?`<ul>${conditions}</ul><small>Confirm these with the employer. They are not scored and are not candidate deficits.</small>`:'<p class="sub">None detected in the supplied text.</p>'}<h3>Tailoring with existing evidence</h3>${tailor||unsupported?`<ul>${unsupported}${tailor}</ul>`:'<p class="sub">No specific evidenced tailoring examples available.</p>'}<div style="margin:16px 0"><b>Hard constraints</b>${hard}</div><h3>Other duties and criteria (need ≥${pc(t?.non_essential?.required)} of those assessed)</h3>${table(otherRows,'None.')}${renderIntelligence(intel)}<h3>Requirement extraction coverage</h3><details><summary>Inspect all ${extraction.source_units} source units, exclusions and unresolved text</summary><table style="width:100%;text-align:left"><thead><tr><th>Unit / treatment</th><th>Source passage / reason</th></tr></thead><tbody>${audit}</tbody></table></details><div class="callout" style="margin-top:15px"><b>Unknown does not mean incapable.</b> “Not checked automatically” means the engine has no matcher; “No CV match found” means a search ran without a match; “Not met (your view)” is your own statement.</div>`;
  }
  function renderIntelligence(intel){
    if(!intel)return '<h3>Limited intelligence</h3><p class="sub">Unavailable. Evidence evaluation is unchanged.</p>';
    if(intel.status==='disabled')return '<h3>Limited intelligence</h3><p class="sub">Disabled for this evaluation. Evidence evaluation is unchanged.</p>';
    const link=(url,label)=>url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);
    const employer=intel.employer;
    const facts=employer?`<div class="callout"><b>Source fact — ${esc(employer.employer)} · ${esc(employer.sector)}</b><p>${esc(employer.fact)}</p><p>${link(employer.source,'Official company source')} · checked ${esc(employer.captured_at)}${employer.stale?' · Snapshot older than 30 days; recheck':''}</p><small>${esc(employer.source_label)}</small><details><summary>Source excerpt and provenance</summary><p>“${esc(employer.excerpt)}”</p><p style="overflow-wrap:anywhere">SHA-256: ${esc(employer.sha256)}</p><small>${esc(employer.hash_scope)}</small></details></div>`:`<p class="sub">${esc(intel.employer_status)}</p>`;
    const questions=intel.questions.map(x=>`<li><b>${esc(x.kind)}</b><p>${esc(x.question)}</p><small>Trigger: “${esc(x.excerpt)}” · ${link(x.source,x.source_type)} · observed ${esc(x.observed_at)}</small></li>`).join('');
    const peers=intel.comparisons.map(x=>`<div class="callout"><b>${link(x.source,x.title)} — ${esc(x.employer)}</b><p>${esc(x.source_type)} · observed ${esc(x.observed_at)}. Text overlap, not equivalent suitability.${x.caution?' '+esc(x.caution):''}</p><p>Shared detected categories: ${x.shared.map(y=>esc(y.label)).join(', ')}</p><p>Only detected in this advert: ${x.only_in_current.map(esc).join(', ')||'None'}. Only detected in the comparison: ${x.only_in_other.map(esc).join(', ')||'None'}.</p><details><summary>Compared source passages and provenance</summary><p style="overflow-wrap:anywhere">SHA-256 of supplied comparison text: ${esc(x.source_sha256||'Unavailable')}</p>${x.shared.map(y=>`<p><b>${esc(y.label)}</b><br>This advert: ${esc(y.current_source_text)}<br>Comparison: ${esc(y.source_text)}</p>`).join('')}</details></div>`).join('');
    return `<h3>Limited intelligence · ${esc(intel.version)}</h3><p class="sub">Enabled · no score or recommendation adjustment · no automatic web research.</p>${facts}<h4>Questions to investigate</h4>${questions?`<ul>${questions}</ul>`:'<p class="sub">No specific contextual question detected.</p>'}<h4>Similar listings in this search</h4>${peers||'<p class="sub">No distinct sourced listing with at least two shared catalogue categories is available.</p>'}<details><summary>Advert provenance and limits</summary><p>${link(intel.advert_source,'Supplied advert source')} · text supplied/observed ${esc(intel.observed_at)}; not a publication date.</p><p style="overflow-wrap:anywhere">SHA-256 of exact supplied advert text: ${esc(intel.advert_sha256||'Unavailable')}</p><p>A fingerprint does not verify authenticity or completeness.</p><ul>${intel.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`;
  }
  el('calEvaluate').onclick=async()=>{
    if(!model){el('calStatus').textContent='Model has not loaded';return}
    const cv=el('matchText')?.value.trim()||'';
    if(cv.length<100){el('calStatus').textContent='First upload or paste your CV in Evidence Matching';return}
    const selection=el('calJob').value,jobs=window.__careerRadarJobs||[];
    const manual=el('calDescription').value.trim();
    const selected=selection!==''?jobs[Number(selection)]:null;
    const linked=Boolean(selected&&el('calLinked').checked);
    const inputNotes=[];
    let job;
    if(manual){
      // Structured facts from a selected listing are reused only when the user says the paste belongs to it.
      const inherited=linked?selected:{};
      const typedUrl=el('calSource').value.trim();
      const url=typedUrl||(linked?(selected.source_url||selected.url):'');
      job={...inherited,title:el('calTitle').value.trim()||inherited.title||'Pasted vacancy',company:el('calEmployer').value.trim()||inherited.company,description:manual,description_kind:el('calFull').checked?'full':'summary',full_description:el('calFull').checked,source_provider:'manual_original',source_url:url,url};
      if(linked)inputNotes.push(`Reused from the selected listing: ${['salary_min','salary_max','location','contract_type','id'].filter(k=>selected[k]!=null&&selected[k]!=='').join(', ')||'nothing'}${selected.salary_is_predicted?' (salary is a provider estimate)':''}.`);
      else if(selected)inputNotes.push('A listing is selected but not linked to this paste; none of its salary, location, contract or ID was reused.');
    }else job=selected;
    if(!job||String(job.description||'').length<30){el('calStatus').textContent='Choose a detailed vacancy or paste its description';return}
    const key=String(job.title)+'\u0000'+String(job.description);if(key!==attestedFor){attestations={};attestedFor=key;}
    if(intelligence&&job.source_url){if(!intelligence.sourceUrl(job.source_url))inputNotes.push('The source URL is not a usable https address (or is a placeholder/reserved domain); it is not shown as the advert source.');else if(intelligence.isDocumentationDomain?.(job.source_url))inputNotes.push('The source URL uses a documentation/test domain (example.com/.org/.net); check it is the real advert address.');}
    if(el('calSector').value)job={...job,sector:el('calSector').value};
    const preferences={salaryFloor:Number(el('calSalary').value)||0,minContractMonths:Number(el('calMonths').value)||0};
    const outcome=model.evaluateV53(cv,job,preferences,attestations);
    const run=++evaluationRun;el('calStatus').textContent='Preparing local context…';
    await intelReady;
    let intel=null;
    if(intelligence){
      intel=intelligence.buildIntelligence({vacancy:job,peers:jobs,evaluationDate:outcome.evaluation_date,enabled:el('calIntel').checked});
      if(intel.status!=='disabled'){
        intel.advert_source=intelligence.sourceUrl(job.source_url||job.url);intel.observed_at=outcome.evaluation_date;
        try{intel.advert_sha256=await intelligence.fingerprint(job.description);for(const peer of intel.comparisons)peer.source_sha256=await intelligence.fingerprint(peer.source_description);}catch{intel.advert_sha256=null;}
      }
    }
    if(run!==evaluationRun)return;
    el('calOutput').innerHTML=render(outcome,job,intel,inputNotes);
    try{if(intelligence){reviewContext={vacancy:structuredClone(job),result:outcome,profileHash:await intelligence.fingerprint(cv),sourceHash:await intelligence.fingerprint(job.description),preferences:structuredClone(preferences)};el('fbRequirement').innerHTML='<option value="">Whole evaluation</option>'+outcome.requirements.map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');el('fbStatus').textContent='Ready for your review of the evaluation above.';}}catch{reviewContext=null;el('fbStatus').textContent='Review provenance could not be prepared; evaluate again.';}

    el('calStatus').textContent='Evaluated locally · no API charge';
  };
  // Checklist answers re-run the local evaluation; they are labelled as the user's own judgement.
  el('calOutput').onchange=e=>{const id=e?.target?.dataset?.attest;if(!id)return;if(e.target.value)attestations[id]=e.target.value;else delete attestations[id];el('calEvaluate').onclick();};
})();
